'use strict';

// Manufacturer lookup from a MAC address prefix, using the public IEEE
// registries (MA-L 24-bit, MA-M 28-bit, MA-S 36-bit prefixes).
// A copy ships with the tool (data/oui.tsv, regenerated by
// scripts/update-oui.js). `lastpatch update-oui` downloads the latest MA-L
// list into a local cache, which then takes precedence for 24-bit prefixes.

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const https = require('node:https');

const IEEE_URL = 'https://standards-oui.ieee.org/oui/oui.csv';
const BUNDLED = path.join(__dirname, '..', 'data', 'oui.tsv');

function cacheFile() {
  if (process.env.LASTPATCH_OUI) return process.env.LASTPATCH_OUI;
  const base = process.env.XDG_CACHE_HOME ||
    (process.platform === 'win32' ? process.env.LOCALAPPDATA : null) ||
    path.join(os.homedir(), '.cache');
  return path.join(base, 'lastpatch', 'oui.csv');
}

// Minimal CSV line parser (quoted fields with commas).
function splitCsv(line) {
  const out = [];
  let cur = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (quoted && line[i + 1] === '"') { cur += '"'; i++; } else quoted = !quoted;
    } else if (c === ',' && !quoted) { out.push(cur); cur = ''; } else cur += c;
  }
  out.push(cur);
  return out;
}

// oui.csv columns: Registry,Assignment,Organization Name,Organization Address
function parseOui(text) {
  const map = new Map();
  for (const line of String(text).split(/\r?\n/).slice(1)) {
    if (!line.trim()) continue;
    const [, assignment, org] = splitCsv(line);
    if (/^[0-9A-F]{6}$/i.test(assignment || '') && org) map.set(assignment.toUpperCase(), org.trim());
  }
  return map;
}

// data/oui.tsv: "PREFIX<TAB>Organisation" per line, prefix of 6, 7 or 9 hex digits.
function parseTsv(text) {
  const map = new Map();
  for (const line of String(text).split(/\r?\n/)) {
    const tab = line.indexOf('\t');
    if (tab < 6) continue;
    const prefix = line.slice(0, tab).toUpperCase();
    if (/^[0-9A-F]{6}([0-9A-F]|[0-9A-F]{3})?$/.test(prefix)) map.set(prefix, line.slice(tab + 1).trim());
  }
  return map;
}

let cached;
function loadOui(file = cacheFile()) {
  if (cached !== undefined) return cached;
  let table = null;
  try { table = parseTsv(fs.readFileSync(BUNDLED, 'utf8')); } catch { /* not shipped */ }
  try {
    const fresh = parseOui(fs.readFileSync(file, 'utf8'));
    table = table || new Map();
    for (const [k, v] of fresh) table.set(k, v);
  } catch { /* no local update */ }
  cached = table && table.size ? table : null;
  return cached;
}

// Longest prefix wins: MA-S (9), then MA-M (7), then MA-L (6).
function vendorOf(mac, table = loadOui()) {
  if (!table || !mac) return null;
  const hex = mac.replace(/[:-]/g, '').toUpperCase();
  return table.get(hex.slice(0, 9)) || table.get(hex.slice(0, 7)) || table.get(hex.slice(0, 6)) || null;
}

function download(url, dest, redirects = 3) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'lastpatch' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && redirects > 0) {
        res.resume();
        return resolve(download(new URL(res.headers.location, url).href, dest, redirects - 1));
      }
      if (res.statusCode !== 200) { res.resume(); return reject(new Error(`IEEE registry: HTTP ${res.statusCode}`)); }
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      const tmp = `${dest}.tmp`;
      const out = fs.createWriteStream(tmp);
      res.pipe(out);
      out.on('finish', () => out.close(() => { fs.renameSync(tmp, dest); resolve(dest); }));
      out.on('error', reject);
    }).on('error', reject);
  });
}

async function updateOui() {
  const dest = cacheFile();
  await download(IEEE_URL, dest);
  cached = undefined;
  const table = loadOui(dest);
  return { file: dest, entries: table ? table.size : 0 };
}

module.exports = { parseOui, parseTsv, vendorOf, loadOui, updateOui, cacheFile };
